96|/* See documentation in header file. */
97|int ini_parse_stream(ini_reader reader, void* stream, ini_handler handler,
98|                     void* user)
99|{
100|    /* Uses a fair bit of stack (use heap instead if you need to) */
101|#if INI_USE_STACK
102|    char line[INI_MAX_LINE];
103|    size_t max_line = INI_MAX_LINE;
104|#else
105|    char* line;
106|    size_t max_line = INI_INITIAL_ALLOC;
107|#endif
108|#if INI_ALLOW_REALLOC && !INI_USE_STACK
109|    char* new_line;
110|#endif
111|    char section[MAX_SECTION] = "";
112|#if INI_ALLOW_MULTILINE
113|    char prev_name[MAX_NAME] = "";
114|#endif
115|
116|    size_t offset;
117|    char* start;
118|    char* end;
119|    char* name;
120|    char* value;
121|    int lineno = 0;
122|    int error = 0;
123|    char abyss[16];  /* Used to consume input when a line is too long. */
124|
125|#if !INI_USE_STACK
126|    line = (char*)ini_malloc(INI_INITIAL_ALLOC);
127|    if (!line) {
128|        return -2;
129|    }
130|#endif
131|
132|#if INI_HANDLER_LINENO
133|#define HANDLER(u, s, n, v) handler(u, s, n, v, lineno)
134|#else
135|#define HANDLER(u, s, n, v) handler(u, s, n, v)
136|#endif
137|
138|    /* Scan through stream line by line */
139|    while (reader(line, (int)max_line, stream) != NULL) {
140|        offset = strlen(line);
141|
142|#if INI_ALLOW_REALLOC && !INI_USE_STACK
143|        while (offset == max_line - 1 && line[offset - 1] != '\n') {
144|            max_line *= 2;
145|            if (max_line > INI_MAX_LINE)
146|                max_line = INI_MAX_LINE;
147|            new_line = ini_realloc(line, max_line);
148|            if (!new_line) {
149|                ini_free(line);
150|                return -2;
151|            }
152|            line = new_line;
153|            if (reader(line + offset, (int)(max_line - offset), stream) == NULL)
154|                break;
155|            offset += strlen(line + offset);
156|            if (max_line >= INI_MAX_LINE)
157|                break;
158|        }
159|#endif
160|
161|        lineno++;
162|
163|        /* If line exceeded INI_MAX_LINE bytes, discard till end of line. */
164|        if (offset == max_line - 1 && line[offset - 1] != '\n') {
165|            while (reader(abyss, sizeof(abyss), stream) != NULL) {
166|                if (!error)
167|                    error = lineno;
168|                if (abyss[strlen(abyss) - 1] == '\n')
169|                    break;
170|            }
171|        }
172|
173|        start = line;
174|#if INI_ALLOW_BOM
175|        if (lineno == 1 && (unsigned char)start[0] == 0xEF &&
176|                           (unsigned char)start[1] == 0xBB &&
177|                           (unsigned char)start[2] == 0xBF) {
178|            start += 3;
179|        }
180|#endif
181|        start = ini_rstrip(ini_lskip(start));
182|
183|        if (strchr(INI_START_COMMENT_PREFIXES, *start)) {
184|            /* Start-of-line comment */
185|        }
186|#if INI_ALLOW_MULTILINE
187|        else if (*prev_name && *start && start > line) {
188|#if INI_ALLOW_INLINE_COMMENTS
189|            end = ini_find_chars_or_comment(start, NULL);
190|            if (*end)
191|                *end = '\0';
192|            ini_rstrip(start);
193|#endif
194|            /* Non-blank line with leading whitespace, treat as continuation
195|               of previous name's value (as per Python configparser). */
196|            if (!HANDLER(user, section, prev_name, start) && !error)
197|                error = lineno;
198|        }
199|#endif
200|        else if (*start == '[') {
201|            /* A "[section]" line */
202|            end = ini_find_chars_or_comment(start + 1, "]");
203|            if (*end == ']') {
204|                *end = '\0';
205|                ini_strncpy0(section, start + 1, sizeof(section));
206|#if INI_ALLOW_MULTILINE
207|                *prev_name = '\0';
208|#endif
209|#if INI_CALL_HANDLER_ON_NEW_SECTION
210|                if (!HANDLER(user, section, NULL, NULL) && !error)
211|                    error = lineno;
212|#endif
213|            }
214|            else if (!error) {
215|                /* No ']' found on section line */
216|                error = lineno;
217|            }
218|        }
219|        else if (*start) {
220|            /* Not a comment, must be a name[=:]value pair */
221|            end = ini_find_chars_or_comment(start, "=:");
222|            if (*end == '=' || *end == ':') {
223|                *end = '\0';
224|                name = ini_rstrip(start);
225|                value = end + 1;
226|#if INI_ALLOW_INLINE_COMMENTS
227|                end = ini_find_chars_or_comment(value, NULL);
228|                if (*end)
229|                    *end = '\0';
230|#endif
231|                value = ini_lskip(value);
232|                ini_rstrip(value);
233|
234|#if INI_ALLOW_MULTILINE
235|                ini_strncpy0(prev_name, name, sizeof(prev_name));
236|#endif
237|                /* Valid name[=:]value pair found, call handler */
238|                if (!HANDLER(user, section, name, value) && !error)
239|                    error = lineno;
240|            }
241|            else {
242|                /* No '=' or ':' found on name[=:]value line */
243|#if INI_ALLOW_NO_VALUE
244|                *end = '\0';
245|                name = ini_rstrip(start);
246|                if (!HANDLER(user, section, name, NULL) && !error)
247|                    error = lineno;
248|#else
249|                if (!error)
250|                    error = lineno;
251|#endif
252|            }
253|        }
254|
255|#if INI_STOP_ON_FIRST_ERROR
256|        if (error)
257|            break;
258|#endif
259|    }
260|
261|#if !INI_USE_STACK
262|    ini_free(line);
263|#endif
264|
265|    return error;
266|}
