288|/* An ini_reader function to read the next line from a string buffer. This
289|   is the fgets() equivalent used by ini_parse_string(). */
290|static char* ini_reader_string(char* str, int num, void* stream) {
291|    ini_parse_string_ctx* ctx = (ini_parse_string_ctx*)stream;
292|    const char* ctx_ptr = ctx->ptr;
293|    size_t ctx_num_left = ctx->num_left;
294|    char* strp = str;
295|    char c;
296|
297|    if (ctx_num_left == 0 || num < 2)
298|        return NULL;
299|
300|    while (num > 1 && ctx_num_left != 0) {
301|        c = *ctx_ptr++;
302|        ctx_num_left--;
303|        *strp++ = c;
304|        if (c == '\n')
305|            break;
306|        num--;
307|    }
308|
309|    *strp = '\0';
310|    ctx->ptr = ctx_ptr;
311|    ctx->num_left = ctx_num_left;
312|    return str;
313|}
