160|int INIReader::ValueHandler(void* user, const char* section, const char* name,
161|                            const char* value)
162|{
163|    if (!name)  // Happens when INI_CALL_HANDLER_ON_NEW_SECTION enabled
164|        return 1;
165|    INIReader* reader = static_cast<INIReader*>(user);
166|    string key = MakeKey(section, name);
167|    if (reader->_values[key].size() > 0)
168|        reader->_values[key] += "\n";
169|    reader->_values[key] += value ? value : "";
170|    return 1;
171|}

